-- Migration 007: Sample Management (Excluding Audit)

CREATE TABLE IF NOT EXISTS samples (
    id SERIAL PRIMARY KEY,
    asset_number VARCHAR(100) NOT NULL UNIQUE,
    model VARCHAR(100) NOT NULL,
    serial_number VARCHAR(100) DEFAULT '',
    category VARCHAR(100) DEFAULT 'Engineering Sample',
    status_pinjam VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE',
    borrower_name VARCHAR(100) DEFAULT '',
    borrowed_at TIMESTAMP WITH TIME ZONE,
    pic_sample VARCHAR(100) DEFAULT '',
    location VARCHAR(255) DEFAULT 'Dynamics Building Lt 2 | PE Lab',
    condition_status VARCHAR(100) DEFAULT 'Normal',
    octa_status VARCHAR(100) DEFAULT '',
    imei VARCHAR(100) DEFAULT '',
    un_code VARCHAR(100) DEFAULT '',
    hw_rev VARCHAR(100) DEFAULT '',
    notes TEXT DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    deleted_at TIMESTAMP WITH TIME ZONE
);

CREATE TABLE IF NOT EXISTS sample_flows (
    id SERIAL PRIMARY KEY,
    sample_id INT REFERENCES samples(id) ON DELETE SET NULL,
    asset_number VARCHAR(100) NOT NULL,
    model VARCHAR(100) NOT NULL,
    borrower_name VARCHAR(100) NOT NULL,
    action VARCHAR(20) NOT NULL,
    notes TEXT DEFAULT '',
    timestamp TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_samples_model ON samples(model);
CREATE INDEX IF NOT EXISTS idx_samples_status_pinjam ON samples(status_pinjam);
CREATE INDEX IF NOT EXISTS idx_samples_borrower ON samples(borrower_name);
CREATE INDEX IF NOT EXISTS idx_sample_flows_asset ON sample_flows(asset_number);

-- Seed initial sample inventory
ON CONFLICT (asset_number) DO NOTHING;

